/* Current room photos, baked in as a plain script so they load on any host
   (the dotfile sidecar gets stripped by GitHub Pages / Jekyll).
   Merges ON TOP of the older images.js so stages only present there survive. */
(function () {
  var base = window.ROOM_IMAGES || {};
  var next = {
    r0: {
      paint: "data:image/webp;base64,",
      furniture: "data:image/webp;base64,",
      styling: "data:image/webp;base64,",
    },
    r1: {
      paint: "data:image/webp;base64,",
      furniture: "data:image/webp;base64,",
      styling: "data:image/webp;base64,",
    },
    r2: {
      current: "data:image/webp;base64,",
      cleared: "data:image/webp;base64,",
      paint: "data:image/webp;base64,",
      furniture: "data:image/webp;base64,",
      styling: "data:image/webp;base64,",
    },
    r3: {
      current: "data:image/webp;base64,",
      cleared: "data:image/webp;base64,",
      paint: "data:image/webp;base64,",
      furniture: "data:image/webp;base64,",
      styling: "data:image/webp;base64,",
    },
    r4: {
      current: "data:image/webp;base64,",
      cleared: "data:image/webp;base64,",
      paint: "data:image/webp;base64,",
      furniture: "data:image/webp;base64,",
      styling: "data:image/webp;base64,",
    },
    r5: {
      current: "data:image/webp;base64,",
      cleared: "data:image/webp;base64,",
      paint: "data:image/webp;base64,",
      furniture: "data:image/webp;base64,",
      styling: "data:image/webp;base64,",
    },
  };
  var out = {};
  Object.keys(base).forEach(function (r) { out[r] = Object.assign({}, base[r]); });
  Object.keys(next).forEach(function (r) { out[r] = Object.assign({}, out[r] || {}, next[r]); });
  window.ROOM_IMAGES = out;
})();
